export function getUseCaseLanguageVariant(
  useCaseSlug: string,
  languageSlug: string
): UseCaseLanguageVariant | undefined {
  return useCaseLanguageVariants.find(
    (v) => v.useCaseSlug === useCaseSlug && v.languageSlug === languageSlug
  );
}
